import{_ as t,H as a,f as i,i as s}from"./chunks/framework.BH2BK_3i.js";const b=JSON.parse('{"title":"加餐 | 什么是大模型，它能帮我们做什么？","description":"","frontmatter":{},"headers":[{"level":3,"title":"大模型能帮我们做什么？","slug":"大模型能帮我们做什么","link":"#大模型能帮我们做什么","children":[]},{"level":3,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":3,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"数据分析思维课/加餐-什么是大模型，它能帮我们做什么？.md","filePath":"数据分析思维课/加餐-什么是大模型，它能帮我们做什么？.md","lastUpdated":1779820765000}'),n={name:"数据分析思维课/加餐-什么是大模型，它能帮我们做什么？.md"};function E(o,e,r,g,p,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="加餐-什么是大模型-它能帮我们做什么" tabindex="-1">加餐 | 什么是大模型，它能帮我们做什么？ <a class="header-anchor" href="#加餐-什么是大模型-它能帮我们做什么" aria-label="Permalink to &quot;加餐 | 什么是大模型，它能帮我们做什么？&quot;">​</a></h1><p>你好，我是郭炜。</p><p>这次的加餐与大模型紧密相关，因为课程之前没有涉及大模型相关内容，可能有的同学不清楚，所以我们就先从“什么是大模型”这个最基础的概念开始讲起。</p><p>&quot;大模型&quot;通常指的是在机器学习和人工智能领域中使用的具有大量参数的模型。这些模型由数百万到数十亿个参数组成，通常通过大规模的数据集进行训练。这些参数使得模型能够更好地理解和表示数据的复杂关系，从而提高其性能和准确性。</p><p>这样说很抽象，简单来说，可以想象一下，如果你有一个超级聪明的朋友，不仅知道很多事情，而且还能学习新东西，并且总是能给你解答问题，那会是怎样的体验？这样的朋友，就像是我们所说的“大模型”。</p><p>大模型，其实就是一种特别强大的电脑程序，它通过阅读和学习海量的书籍、文章、网页等信息，来理解和使用语言。就像是把整个图书馆的知识都装进了它的“大脑”里。这样，当你向它提问或请求帮助时，它可以用它学到的知识来回答你。它背后有着非常复杂的数学和计算机科学原理，所以他可以解答各种复杂的问题，简单来说，就是因为它能够从大量的数据中学习到如何理解和生成语言，这让它变得非常聪明。</p><p>而大模型工作的原理，你可以想象成是在做匹配游戏。当你问它一个问题时，它会在它的“知识库”里寻找最匹配的信息，然后根据这些信息给出答案。而这个“知识库”是通过之前学习到的所有信息构建的，所以它的回答通常都很有用。</p><h3 id="大模型能帮我们做什么" tabindex="-1">大模型能帮我们做什么？ <a class="header-anchor" href="#大模型能帮我们做什么" aria-label="Permalink to &quot;大模型能帮我们做什么？&quot;">​</a></h3><p>大模型就像是一个万能助手，可以帮你写作业、编程、创作故事或音乐，甚至帮你学习新的语言。因为它学习了很多知识，所以不管你遇到什么问题，只要问它，它都能给你一些帮助，比如下面这些方面。</p><p><strong>教育辅助</strong>：学生可以使用大模型来获取对复杂概念的解释，比如请求解释量子物理的基本原理，或者获取数学题目的解题步骤。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/5c54904cfb745c730b1400e629f2b08d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/5c54904cfb745c730b1400e629f2b08d.png" alt="图片"></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/d6e9b7c3ef18a15da451ef55273f8ba8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/d6e9b7c3ef18a15da451ef55273f8ba8.png" alt="图片"></a></p><p><strong>内容创作</strong>：作家或市场营销人员可以使用大模型生成创意写作文本、广告副本或博客文章草稿，节省时间并激发新的创意。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/c40a99e11d043a0414c8594068d6cf13.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/c40a99e11d043a0414c8594068d6cf13.png" alt="图片"></a></p><p><strong>编程辅助</strong>：开发者可以借助大模型来生成代码片段、调试代码或理解复杂的编程概念，加速软件开发过程。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/5b2d1e15eefa038932096c73b10a2a6c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/5b2d1e15eefa038932096c73b10a2a6c.png" alt="图片"></a></p><p><strong>语言学习</strong>： 语言学习者可以使用大模型练习对话、纠正语法错误或学习新词汇，作为互动的语言学习工具。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/4abc84a6d9764837cb38577e50960536.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/4abc84a6d9764837cb38577e50960536.png" alt="图片"></a></p><p><strong>个人生产力提升</strong>：个人可以利用大模型来管理日程、设置提醒、整理邮件等，提高日常工作和生活的效率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/ee77381eed9b0ba7c1d12f4072657da8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/ee77381eed9b0ba7c1d12f4072657da8.png" alt="图片"></a></p><p><strong>旅行规划与建议</strong>：用户可以获取关于目的地的详细信息、旅行建议、行程规划帮助，甚至语言翻译服务，使旅行准备更加轻松。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/b7dd95b43063a8046d6c6728f37e32c7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/b7dd95b43063a8046d6c6728f37e32c7.png" alt="图片"></a></p><p><strong>广告创意与图画</strong>：大模型还可以做很多事情，你可以有一个创意让它来画Logo，或者有一个创意让它把图片画出来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/6876d9480ff788ea8e6yya6b3753daf9.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E5%88%86%E6%9E%90%E6%80%9D%E7%BB%B4%E8%AF%BE/images/841696/6876d9480ff788ea8e6yya6b3753daf9.jpg" alt="图片"></a></p><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h3><p>这节课的内容安排主要起到一个总览的作用，给你讲解了大模型的基础概念，以及大模型可以在工作生活的哪些方面帮到我们。大模型就像是一个知识无限、永远不会累的超级智能助手，它通过学习大量的文本信息，来帮助我们解答问题、完成任务。对于我们来说，学会如何使用这样的工具，就像是学会了如何和这个超级智能朋友合作，一起完成更多的事情。下节课我们会进一步聚焦，深度使用大模型来解决数据分析领域当中的各种问题。</p><h3 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h3><p>在你工作和生活当中，你觉得还有哪些问题可以让大模型帮你解决？哪些问题大模型是不可以帮你解决的？为什么？</p>',28)])])}const l=t(n,[["render",E]]);export{b as __pageData,l as default};
